<?php
namespace Modules\Ran\Reports;
class ProfitReport extends AbstractRanReport{public function title():string{return 'Sales Profit';}public function headings():array{return ['Invoice No','Date','Customer','Revenue','Cost','Gross Profit'];}public function rows(array $f):array{$q=\DB::table('ran_sales as s')->join('ran_sale_lines as l','l.sale_id','=','s.id')->whereNull('s.deleted_at')->whereNull('l.deleted_at')->where('s.status','posted');$this->filter($q,$f,'s.invoice_date','s');return $q->groupBy('s.id','s.invoice_no','s.invoice_date','s.customer_name','s.total_amount')->orderByDesc('s.invoice_date')->get(['s.invoice_no','s.invoice_date','s.customer_name',\DB::raw('s.total_amount revenue'),\DB::raw('SUM(l.cost_amount) cost'),\DB::raw('s.total_amount-SUM(l.cost_amount) gross_profit')])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Revenue'=>array_sum(array_column($rows,'revenue')),'Cost'=>array_sum(array_column($rows,'cost')),'Gross Profit'=>array_sum(array_column($rows,'gross_profit'))];}}
